package forth

import (
	"fmt"
	"strconv"
	"strings"
)

// Forth evaluates a very simple subset of the Forth language.
//
// It supports integer arithmetic (+, -, *, /), stack manipulation
// (dup, drop, swap, over), and user-defined words introduced with the
// customary syntax ": word-name definition ;". Words are case-insensitive.
func Forth(input []string) ([]int, error) {
	stack := []int{}
	words := map[string][]string{}

	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); i++ {
			if tokens[i] != ":" {
				if err := execToken(tokens[i], &stack, words); err != nil {
					return nil, err
				}
				continue
			}
			// A definition: ": name body... ;"
			if i+2 >= len(tokens) {
				return nil, fmt.Errorf("malformed definition")
			}
			name := strings.ToLower(tokens[i+1])
			if isNumber(name) {
				return nil, fmt.Errorf("cannot redefine a number")
			}
			semi := -1
			for j := i + 2; j < len(tokens); j++ {
				if tokens[j] == ";" {
					semi = j
					break
				}
			}
			if semi < 0 {
				return nil, fmt.Errorf("unterminated definition")
			}
			words[name] = compile(tokens[i+2:semi], words)
			i = semi
		}
	}
	return stack, nil
}

// compile resolves references to user-defined words at definition time,
// so that a word keeps the meaning of the words it was defined with
// (like compilation in real Forth).
func compile(body []string, words map[string][]string) []string {
	out := make([]string, 0, len(body))
	for _, tok := range body {
		if def, ok := words[strings.ToLower(tok)]; ok {
			out = append(out, def...)
		} else {
			out = append(out, tok)
		}
	}
	return out
}

// execToken executes a single token: a number, a user-defined word, or a
// built-in word.
func execToken(tok string, stack *[]int, words map[string][]string) error {
	if n, ok := parseNumber(tok); ok {
		*stack = append(*stack, n)
		return nil
	}
	lower := strings.ToLower(tok)
	if def, ok := words[lower]; ok {
		for _, t := range def {
			if err := execToken(t, stack, words); err != nil {
				return err
			}
		}
		return nil
	}
	if f, ok := builtins[lower]; ok {
		return f(stack)
	}
	return fmt.Errorf("undefined operation %q", tok)
}

type stackOp func(*[]int) error

// builtins holds the built-in words, keyed by their lowercase name.
var builtins = map[string]stackOp{
	"+": func(s *[]int) error {
		a, b, err := popTwo(s)
		if err != nil {
			return err
		}
		*s = append(*s, a+b)
		return nil
	},
	"-": func(s *[]int) error {
		a, b, err := popTwo(s)
		if err != nil {
			return err
		}
		*s = append(*s, a-b)
		return nil
	},
	"*": func(s *[]int) error {
		a, b, err := popTwo(s)
		if err != nil {
			return err
		}
		*s = append(*s, a*b)
		return nil
	},
	"/": func(s *[]int) error {
		a, b, err := popTwo(s)
		if err != nil {
			return err
		}
		if b == 0 {
			return fmt.Errorf("divide by zero")
		}
		*s = append(*s, a/b)
		return nil
	},
	"dup": func(s *[]int) error {
		if len(*s) == 0 {
			return fmt.Errorf("empty stack")
		}
		*s = append(*s, (*s)[len(*s)-1])
		return nil
	},
	"drop": func(s *[]int) error {
		if len(*s) == 0 {
			return fmt.Errorf("empty stack")
		}
		*s = (*s)[:len(*s)-1]
		return nil
	},
	"swap": func(s *[]int) error {
		a, b, err := popTwo(s)
		if err != nil {
			return err
		}
		*s = append(*s, b, a)
		return nil
	},
	"over": func(s *[]int) error {
		if len(*s) < 2 {
			if len(*s) == 0 {
				return fmt.Errorf("empty stack")
			}
			return fmt.Errorf("only one value on the stack")
		}
		*s = append(*s, (*s)[len(*s)-2])
		return nil
	},
}

// popTwo pops the top two values, returning the second-from-top first.
func popTwo(s *[]int) (a, b int, err error) {
	if len(*s) == 0 {
		return 0, 0, fmt.Errorf("empty stack")
	}
	b = (*s)[len(*s)-1]
	*s = (*s)[:len(*s)-1]
	if len(*s) == 0 {
		return 0, 0, fmt.Errorf("only one value on the stack")
	}
	a = (*s)[len(*s)-1]
	*s = (*s)[:len(*s)-1]
	return a, b, nil
}

// parseNumber reports whether tok is a (possibly negative) integer.
func parseNumber(tok string) (int, bool) {
	n, err := strconv.Atoi(tok)
	if err != nil {
		return 0, false
	}
	return n, true
}

func isNumber(tok string) bool {
	_, ok := parseNumber(tok)
	return ok
}

